    const categoryMap = new Map<string, number[]>();
  
    // 予測データと実績データをマッチングして乖離率を計算
    for (const pred of predictionData) {
      const matching = actualData.find(
        (act) => act.date === pred.date && act.category === pred.category
      );
  
      if (matching) {
        const deviationRate =
          Math.abs(matching.actual - pred.predicted) / pred.predicted;
  
        if (!categoryMap.has(pred.category)) {
          categoryMap.set(pred.category, []);
        }
        categoryMap.get(pred.category)!.push(deviationRate);
      }
    }
  
    // カテゴリごとの平均乖離率を計算
    const result: CategoryDeviationAnalysis[] = [];
  
    for (const [category, deviations] of categoryMap.entries()) {
      const averageDeviation =
        deviations.reduce((sum, rate) => sum + rate, 0) / deviations.length;
      const deviationRatePercent = Math.round(averageDeviation * 1000) / 10; // 小数第1位まで
  
      result.push({
        category,
        deviationRate: deviationRatePercent,
        deviationCount: deviations.length,
      });
    }
  
    return result;
