const __aivicBundle_10_analyzeDiscrepancy = (() => {
  function analyzeDiscrepancy(dataset: {
    predictedDemand: Array<number | null>;
    actualDemand: Array<number>;
    category: string;
    period: string;
  }): {
    meanAbsoluteError: number;
    rootMeanSquaredError: number;
    discrepancyRate: number;
  } {
    if (dataset["category"] === undefined || dataset["category"] === null) { throw new Error("category is required"); }
    if (dataset["period"] === undefined || dataset["period"] === null) { throw new Error("period is required"); }
    const { predictedDemand, actualDemand } = dataset;
  
    // Validate predictedDemand for null, non-numeric, or invalid values
    for (let i = 0; i < predictedDemand.length; i++) {
      const val = predictedDemand[i];
      if (val === null || val === undefined) {
        throw new Error('実績データにNULL値が含まれています');
      }
      if (typeof val !== 'number' || isNaN(val)) {
        throw new Error('予測データに不正な値が含まれています');
      }
    }
  
    // Validate actualDemand for negative, non-numeric, or invalid values
    for (let i = 0; i < actualDemand.length; i++) {
      const val = actualDemand[i];
      if (typeof val !== 'number' || isNaN(val)) {
        throw new Error('実績データに不正な値が含まれています');
      }
      if (val < 0) {
        throw new Error('実績データに不正な値が含まれています');
      }
    }
  
    // Ensure arrays have the same length
    if (predictedDemand.length !== actualDemand.length) {
      throw new Error('予測データと実績データの長さが一致しません');
    }
  
    if (predictedDemand.length === 0) {
      throw new Error('データセットが空です');
    }
  
    // Calculate Mean Absolute Error (MAE)
    let sumAbsoluteError = 0;
    for (let i = 0; i < predictedDemand.length; i++) {
      sumAbsoluteError += Math.abs(predictedDemand[i] - actualDemand[i]);
    }
    const meanAbsoluteError = sumAbsoluteError / predictedDemand.length;
  
    // Calculate Root Mean Squared Error (RMSE)
    let sumSquaredError = 0;
    for (let i = 0; i < predictedDemand.length; i++) {
      const error = predictedDemand[i] - actualDemand[i];
      sumSquaredError += error * error;
    }
    const rootMeanSquaredError = Math.sqrt(sumSquaredError / predictedDemand.length);
  
    // Calculate average actual demand
    let sumActualDemand = 0;
    for (let i = 0; i < actualDemand.length; i++) {
      sumActualDemand += actualDemand[i];
    }
    const averageActualDemand = sumActualDemand / actualDemand.length;
  
    // Calculate discrepancy rate (as percentage)
    let discrepancyRate = 0;
    if (averageActualDemand !== 0) {
      discrepancyRate = (meanAbsoluteError / averageActualDemand) * 100;
    }
  
    // Round to 2 decimal places for consistency
    return {
      meanAbsoluteError: Math.round(meanAbsoluteError * 100) / 100,
      rootMeanSquaredError: Math.round(rootMeanSquaredError * 100) / 100,
      discrepancyRate: Math.round(discrepancyRate * 100) / 100,
    };
  }
  return { analyzeDiscrepancy };
})();
export const analyzeDiscrepancy = __aivicBundle_10_analyzeDiscrepancy.analyzeDiscrepancy;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzeDiscrepancy */

