const __aivicBundle_14_normalizeCorrelationCoefficient = (() => {
  function normalizeCorrelationCoefficient(value: number): number {
    if (value < -1.0) {
      return -1.0;
    }
    if (value > 1.0) {
      return 1.0;
    }
    return value;
  }
  return { normalizeCorrelationCoefficient };
})();
