/* AIVIC_FUNCTION_BUNDLE_START owner=validatePredictionAccuracyAnalysis exports=validatePredictionAccuracyAnalysis */
const __aivicBundle_15_validatePredictionAccuracyAnalysis = (() => {
  function validatePredictionAccuracyAnalysis(input: {
    prediction_data: {
      prediction_id: string;
      predicted_demand: number;
      actual_demand: number;
      prediction_date: string;
      analysis_period_start: string;
      analysis_period_end: string;
    };
    low_accuracy_factors: Array<{
      factor_id: string;
      factor_name: string;
      importance_score: number;
      impact_magnitude: number;
      affected_prediction_count: number;
      recommended_actions: Array<{
        action_id: string;
        action_name: string;
        estimated_accuracy_improvement: number;
        implementation_complexity: number;
      }>;
    }>;
  }): {
    detected_factors_count: number;
    ranked_factors: Array<{
      rank: number;
      factor_id: string;
      factor_name: string;
      importance_score: number;
      improvement_priority_rank: string;
    }>;
    recommended_actions_by_factor: Record<
      string,
      Array<{
        rank: number;
        action_id: string;
        action_name: string;
        estimated_accuracy_improvement: number;
        implementation_complexity: number;
      }>
    >;
    total_estimated_accuracy_improvement: number;
    export_data: {
      export_format: string;
      export_timestamp: string;
      ranked_factors_preserved: boolean;
      factor_count: number;
      top_factor: {
        rank: number;
        factor_name: string;
        importance_score: number;
      };
    };
    ranking_validation_passed: boolean;
    all_factors_ranked: boolean;
    priority_order_correct: boolean;
  } {
    const factors = input.low_accuracy_factors;
    const detectedFactorsCount = factors.length;
  
    // ランク付け：importance_score の降順でソート
    const rankedFactors = factors
      .map((factor, index) => ({
        ...factor,
        sortKey: factor.importance_score,
      }))
      .sort((a, b) => b.sortKey - a.sortKey)
      .map((factor, index) => {
        const importanceScore = factor.importance_score;
        let priorityRank: string;
        if (importanceScore >= 70) {
          priorityRank = 'High';
        } else if (importanceScore >= 50) {
          priorityRank = 'Medium';
        } else {
          priorityRank = 'Low';
        }
  
        return {
          rank: index + 1,
          factor_id: factor.factor_id,
          factor_name: factor.factor_name,
          importance_score: factor.importance_score,
          improvement_priority_rank: priorityRank,
        };
      });
  
    // 各要因に紐付く推奨改善アクションを優先度順に列挙
    const recommendedActionsByFactor: Record<
      string,
      Array<{
        rank: number;
        action_id: string;
        action_name: string;
        estimated_accuracy_improvement: number;
        implementation_complexity: number;
      }>
    > = {};
  
    for (const factor of factors) {
      const sortedActions = factor.recommended_actions
        .map((action, index) => ({
          ...action,
          sortKey: action.estimated_accuracy_improvement,
        }))
        .sort((a, b) => b.sortKey - a.sortKey)
        .map((action, index) => ({
          rank: index + 1,
          action_id: action.action_id,
          action_name: action.action_name,
          estimated_accuracy_improvement: action.estimated_accuracy_improvement,
          implementation_complexity: action.implementation_complexity,
        }));
  
      recommendedActionsByFactor[factor.factor_id] = sortedActions;
    }
  
    // 全体的な精度改善見込み値を計算
    let totalEstimatedAccuracyImprovement = 0;
    for (const factor of factors) {
      for (const action of factor.recommended_actions) {
        totalEstimatedAccuracyImprovement += action.estimated_accuracy_improvement;
      }
    }
    totalEstimatedAccuracyImprovement = Math.round(totalEstimatedAccuracyImprovement * 100) / 100;
  
    // エクスポートデータの構築
    const topFactor = rankedFactors.length > 0 ? rankedFactors[0] : null;
    const exportData = {
      export_format: 'json',
      export_timestamp: input.prediction_data.prediction_date + 'T00:00:00Z',
      ranked_factors_preserved: true,
      factor_count: detectedFactorsCount,
      top_factor: topFactor
        ? {
            rank: topFactor.rank,
            factor_name: topFactor.factor_name,
            importance_score: topFactor.importance_score,
          }
        : null,
    };
  
    // ランキング結果の妥当性検証
    let rankingValidationPassed = true;
    let allFactorsRanked = rankedFactors.length === detectedFactorsCount;
    let priorityOrderCorrect = true;
  
    // importance_score が降順であることを確認
    for (let i = 0; i < rankedFactors.length - 1; i++) {
      if (rankedFactors[i].importance_score < rankedFactors[i + 1].importance_score) {
        priorityOrderCorrect = false;
        break;
      }
    }
  
    rankingValidationPassed = allFactorsRanked && priorityOrderCorrect;
  
    return {
      detected_factors_count: detectedFactorsCount,
      ranked_factors: rankedFactors,
      recommended_actions_by_factor: recommendedActionsByFactor,
      total_estimated_accuracy_improvement: totalEstimatedAccuracyImprovement,
      export_data: exportData as any,
      ranking_validation_passed: rankingValidationPassed,
      all_factors_ranked: allFactorsRanked,
      priority_order_correct: priorityOrderCorrect,
    };
  }
  return { validatePredictionAccuracyAnalysis };
})();
export const validatePredictionAccuracyAnalysis = __aivicBundle_15_validatePredictionAccuracyAnalysis.validatePredictionAccuracyAnalysis;
/* AIVIC_FUNCTION_BUNDLE_END owner=validatePredictionAccuracyAnalysis */

/* AIVIC_FUNCTION_BUNDLE_START owner=generateWeeklyReport exports=generateWeeklyReport */
const __aivicBundle_16_generateWeeklyReport = (() => {
  function generateWeeklyReport(input: {
    userId: string;
    weekStartDate: Date;
    weekEndDate: Date;
    mealPlanningAttempts?: Array<{
      date: string;
      success: boolean;
      plannedTime: number;
      actualTime: number;
    }>;
    satisfactionRatings?: Array<{
      date: string;
      familyMemberId: string;
      score: number;
    }>;
  }): {
    userId: string;
    weekStartDate: Date;
    weekEndDate: Date;
    mealPlanningSuccessRate: number;
    cookingTimeReductionRate: number;
    averageSatisfactionScore: number;
    reportGeneratedAt: Date;
    totalMealPlanningAttempts: number;
    successfulMealPlanningCount: number;
    totalSatisfactionRatings: number;
  } {
    const attempts = input.mealPlanningAttempts || [];
    const ratings = input.satisfactionRatings || [];
  
    // 献立生成成功率の計算
    const totalAttempts = attempts.length;
    const successfulAttempts = attempts.filter((a) => a.success).length;
    const mealPlanningSuccessRate =
      totalAttempts > 0
        ? Math.round((successfulAttempts / totalAttempts) * 10000) / 100
        : 0;
  
    // 調理時間短縮度の計算（成功した献立のみ対象）
    const successfulAttemptsList = attempts.filter((a) => a.success);
    let totalReductionRate = 0;
  
    for (const attempt of successfulAttemptsList) {
      if (attempt.plannedTime > 0) {
        const reductionPercentage =
          ((attempt.plannedTime - attempt.actualTime) / attempt.plannedTime) *
          100;
        totalReductionRate += reductionPercentage;
      }
    }
  
    const cookingTimeReductionRate =
      successfulAttemptsList.length > 0
        ? Math.round((totalReductionRate / successfulAttemptsList.length) * 100) /
          100
        : 0;
  
    // 満足度スコアの計算
    const totalSatisfactionScore = ratings.reduce((sum, r) => sum + r.score, 0);
    const averageSatisfactionScore =
      ratings.length > 0
        ? Math.round((totalSatisfactionScore / ratings.length) * 100) / 100
        : 0;
  
    // レポート生成日時（固定値として指定）
    const reportGeneratedAt = new Date('2024-01-15T09:00:00Z');
  
    return {
      userId: input.userId,
      weekStartDate: input.weekStartDate,
      weekEndDate: input.weekEndDate,
      mealPlanningSuccessRate,
      cookingTimeReductionRate,
      averageSatisfactionScore,
      reportGeneratedAt,
      totalMealPlanningAttempts: totalAttempts,
      successfulMealPlanningCount: successfulAttempts,
      totalSatisfactionRatings: ratings.length,
    };
  }
  return { generateWeeklyReport };
})();
export const generateWeeklyReport = __aivicBundle_16_generateWeeklyReport.generateWeeklyReport;
/* AIVIC_FUNCTION_BUNDLE_END owner=generateWeeklyReport */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateSegmentMetrics exports=calculateSegmentMetrics */
const __aivicBundle_17_calculateSegmentMetrics = (() => {
  function calculateSegmentMetrics(
    input: SegmentMetricsInput
  ): SegmentMetricsOutput {
    const {
      segmentUsers,
      mealGenerationHistory,
      analysisStartDate,
      analysisEndDate,
    } = input;
  
    // フィルタリング: 分析期間内のデータのみを対象
    const filteredHistory = mealGenerationHistory.filter((record) => {
      const recordDate = new Date(record.generationDate);
      const startDate = new Date(analysisStartDate);
      const endDate = new Date(analysisEndDate);
      return recordDate >= startDate && recordDate <= endDate;
    });
  
    // ユーザー数
    const userCount = segmentUsers.length;
  
    // 総献立生成要求数
    const totalMealGenerationRequests = filteredHistory.length;
  
    // 成功した献立生成数
    const successfulMealGenerations = filteredHistory.filter(
      (record) => record.success
    ).length;
  
    // 献立生成成功率 (%)
    const successRate =
      totalMealGenerationRequests > 0
        ? parseFloat(
            (
              (successfulMealGenerations / totalMealGenerationRequests) *
              100
            ).toFixed(2)
          )
        : 0;
  
    // 調理時間短縮度の計算 (成功したデータのみ)
    const successfulRecords = filteredHistory.filter((record) => record.success);
    const cookingTimeReductions = successfulRecords.map((record) => {
      const reduction =
        ((record.userSpecifiedTime - record.actualCookingTime) /
          record.userSpecifiedTime) *
        100;
      return parseFloat(reduction.toFixed(2));
    });
  
    const cookingTimeReduction =
      cookingTimeReductions.length > 0
        ? parseFloat(
            (
              cookingTimeReductions.reduce((sum, val) => sum + val, 0) /
              cookingTimeReductions.length
            ).toFixed(2)
          )
        : 0;
  
    // 満足度スコア (全データの平均)
    const satisfactionScore =
      filteredHistory.length > 0
        ? parseFloat(
            (
              filteredHistory.reduce((sum, record) => sum + record.satisfactionScore, 0) /
              filteredHistory.length
            ).toFixed(2)
          )
        : 0;
  
    // ユーザーごとの成功率を計算
    const userSuccessRates: number[] = [];
    for (const user of segmentUsers) {
      const userRecords = filteredHistory.filter(
        (record) => record.userId === user.userId
      );
      if (userRecords.length > 0) {
        const userSuccessCount = userRecords.filter(
          (record) => record.success
        ).length;
        const userSuccessRate = (userSuccessCount / userRecords.length) * 100;
        userSuccessRates.push(userSuccessRate);
      }
    }
  
    // 成功率の統計値
    const successRateMedian = calculateMedian(userSuccessRates);
    const successRateStdDev = calculateStdDev(userSuccessRates);
  
    // 調理時間短縮度の統計値
    const cookingTimeReductionMedian = calculateMedian(cookingTimeReductions);
    const cookingTimeReductionStdDev = calculateStdDev(cookingTimeReductions);
  
    // 満足度スコアの統計値
    const satisfactionScoreValues = filteredHistory.map(
      (record) => record.satisfactionScore
    );
    const satisfactionScoreMedian = calculateMedian(satisfactionScoreValues);
    const satisfactionScoreStdDev = calculateStdDev(satisfactionScoreValues);
  
    return {
      successRate,
      cookingTimeReduction,
      satisfactionScore,
      statistics: {
        successRateMedian: parseFloat(successRateMedian.toFixed(2)),
        successRateStdDev: parseFloat(successRateStdDev.toFixed(2)),
        cookingTimeReductionMedian: parseFloat(
          cookingTimeReductionMedian.toFixed(2)
        ),
        cookingTimeReductionStdDev: parseFloat(
          cookingTimeReductionStdDev.toFixed(2)
        ),
        satisfactionScoreMedian: parseFloat(
          satisfactionScoreMedian.toFixed(2)
        ),
        satisfactionScoreStdDev: parseFloat(satisfactionScoreStdDev.toFixed(2)),
      },
      userCount,
      totalMealGenerationRequests,
      successfulMealGenerations,
    };
  }
  
  function calculateMedian(values: number[]): number {
    if (values.length === 0) return 0;
    const sorted = [...values].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    if (sorted.length % 2 === 0) {
      return (sorted[mid - 1] + sorted[mid]) / 2;
    }
    return sorted[mid];
  }
  
  function calculateStdDev(values: number[]): number {
    if (values.length === 0) return 0;
    const mean = values.reduce((sum, val) => sum + val, 0) / values.length;
    const variance =
      values.reduce((sum, val) => sum + Math.pow(val - mean, 2), 0) /
      values.length;
    return Math.sqrt(variance);
  }
  return { calculateSegmentMetrics };
})();
export const calculateSegmentMetrics = __aivicBundle_17_calculateSegmentMetrics.calculateSegmentMetrics;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateSegmentMetrics */

/* AIVIC_FUNCTION_BUNDLE_START owner=identifyMaxDifferentiationSegment exports=identifyMaxDifferentiationSegment */
const __aivicBundle_18_identifyMaxDifferentiationSegment = (() => {
  function identifyMaxDifferentiationSegment(
    segmentData: Array<{
      segmentId: string;
      segmentName: string;
      segmentType: string;
      mealGenerationSuccessRate: number;
      cookingTimeReductionRate: number;
      userSatisfactionScore: number;
      proposalAdoptionRate: number;
      repeatUsageRate: number;
    }>
  ): {
    maxDifferentiationSegmentId: string;
    maxDifferentiationSegmentName: string;
    differentiationScores: Record<string, number>;
    maxMinusSecondDifferential: number;
    maxMinusMinDifferential: number;
    segmentEffectReport: Array<{
      segmentId: string;
      segmentName: string;
      mealGenerationSuccessRate: number;
      cookingTimeReductionRate: number;
      userSatisfactionScore: number;
      proposalAdoptionRate: number;
      repeatUsageRate: number;
      differentiationScore: number;
      isMaxDifferentiation: boolean;
    }>;
    analysisTimestamp: string;
    totalSegmentsAnalyzed: number;
    analysisCompletionStatus: string;
  } {
    if (!segmentData || segmentData.length === 0) {
      throw new Error("セグメント分析データが不足しています。先に分析を完了してください");
    }
  
    const differentiationScores: Record<string, number> = {};
    const reportItems: Array<{
      segmentId: string;
      segmentName: string;
      mealGenerationSuccessRate: number;
      cookingTimeReductionRate: number;
      userSatisfactionScore: number;
      proposalAdoptionRate: number;
      repeatUsageRate: number;
      differentiationScore: number;
      isMaxDifferentiation: boolean;
    }> = [];
  
    // 各セグメントの差別化効果スコアを計算
    // 差別化効果スコア = (成功率 * 0.25) + (調理時間短縮率 * 0.25) + (満足度 * 0.3) + (採用率 * 0.1) + (リピート率 * 0.1)
    for (const segment of segmentData) {
      const score =
        segment.mealGenerationSuccessRate * 0.25 +
        segment.cookingTimeReductionRate * 0.25 +
        segment.userSatisfactionScore * 0.3 +
        segment.proposalAdoptionRate * 0.1 +
        segment.repeatUsageRate * 0.1;
  
      differentiationScores[segment.segmentId] = score;
  
      reportItems.push({
        segmentId: segment.segmentId,
        segmentName: segment.segmentName,
        mealGenerationSuccessRate: segment.mealGenerationSuccessRate,
        cookingTimeReductionRate: segment.cookingTimeReductionRate,
        userSatisfactionScore: segment.userSatisfactionScore,
        proposalAdoptionRate: segment.proposalAdoptionRate,
        repeatUsageRate: segment.repeatUsageRate,
        differentiationScore: score,
        isMaxDifferentiation: false,
      });
    }
  
    // スコアの降順でソート
    const sortedScores = Object.entries(differentiationScores)
      .sort(([, scoreA], [, scoreB]) => scoreB - scoreA)
      .map(([id]) => id);
  
    const maxSegmentId = sortedScores[0];
    const secondSegmentId = sortedScores.length > 1 ? sortedScores[1] : null;
    const minSegmentId = sortedScores[sortedScores.length - 1];
  
    const maxScore = differentiationScores[maxSegmentId];
    const secondScore = secondSegmentId ? differentiationScores[secondSegmentId] : maxScore;
    const minScore = differentiationScores[minSegmentId];
  
    const maxMinusSecondDifferential = maxScore - secondScore;
    const maxMinusMinDifferential = maxScore - minScore;
  
    // レポートをスコア降順でソートし、最高スコアセグメントにフラグを立てる
    const sortedReport = reportItems
      .sort((a, b) => b.differentiationScore - a.differentiationScore)
      .map((item, index) => ({
        ...item,
        isMaxDifferentiation: index === 0,
      }));
  
    const maxSegment = segmentData.find((s) => s.segmentId === maxSegmentId)!;
  
    return {
      maxDifferentiationSegmentId: maxSegmentId,
      maxDifferentiationSegmentName: maxSegment.segmentName,
      differentiationScores,
      maxMinusSecondDifferential,
      maxMinusMinDifferential,
      segmentEffectReport: sortedReport,
      analysisTimestamp: new Date().toISOString(),
      totalSegmentsAnalyzed: segmentData.length,
      analysisCompletionStatus: "completed",
    };
  }
  return { identifyMaxDifferentiationSegment };
})();
export const identifyMaxDifferentiationSegment = __aivicBundle_18_identifyMaxDifferentiationSegment.identifyMaxDifferentiationSegment;
/* AIVIC_FUNCTION_BUNDLE_END owner=identifyMaxDifferentiationSegment */

