/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateMonthlyCostAndSatisfaction exports=aggregateMonthlyCostAndSatisfaction */
const __aivicBundle_20_aggregateMonthlyCostAndSatisfaction = (() => {
  function aggregateMonthlyCostAndSatisfaction(
    input: MonthlyCostInput
  ): MonthlyCostOutput {
    const { mealRecords, monthlyBudget, currentDate } = input;
  
    // 月次食費実績を計算（全食事記録コストの合計）
    const monthlyTotalCost = mealRecords.reduce(
      (sum, record) => sum + record.totalCost,
      0
    );
  
    // 予算比削減率を計算
    const budgetReductionRate =
      ((monthlyBudget - monthlyTotalCost) / monthlyBudget) * 100;
  
    // 食材別コスト分析を集計
    const ingredientMap = new Map<
      string,
      { ingredientId: string; ingredientName: string; totalCost: number; usageCount: number }
    >();
  
    mealRecords.forEach((record) => {
      record.ingredients.forEach((ingredient) => {
        const key = ingredient.ingredientId;
        if (ingredientMap.has(key)) {
          const existing = ingredientMap.get(key)!;
          existing.totalCost += ingredient.cost * ingredient.quantity;
          existing.usageCount += 1;
        } else {
          ingredientMap.set(key, {
            ingredientId: ingredient.ingredientId,
            ingredientName: ingredient.ingredientName,
            totalCost: ingredient.cost * ingredient.quantity,
            usageCount: 1,
          });
        }
      });
    });
  
    const ingredientCostAnalysis = Array.from(ingredientMap.values());
  
    // 満足度スコアの平均を計算
    const averageSatisfactionScore =
      mealRecords.length > 0
        ? mealRecords.reduce((sum, record) => sum + record.satisfactionScore, 0) /
          mealRecords.length
        : 0;
  
    // 月を抽出（YYYY-MM形式）
    const month = currentDate.substring(0, 7);
  
    return {
      monthlyTotalCost,
      budgetReductionRate,
      ingredientCostAnalysis,
      averageSatisfactionScore,
      month,
      isSuccessfullyAggregated: true,
    };
  }
  return { aggregateMonthlyCostAndSatisfaction };
})();
export const aggregateMonthlyCostAndSatisfaction = __aivicBundle_20_aggregateMonthlyCostAndSatisfaction.aggregateMonthlyCostAndSatisfaction;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateMonthlyCostAndSatisfaction */

