const __aivicBundle_25_detectAnomaliesInMealEvaluations = (() => {
  function detectAnomaliesInMealEvaluations(
    aggregated_evaluations: EvaluationRecord[]
  ): AnomalyDetectionResult {
    const anomalyFlags: string[] = [];
    const filtered_evaluations: EvaluationRecord[] = [];
  
    const SATISFACTION_MIN = 1;
    const SATISFACTION_MAX = 5;
    const COMPLETION_MIN = 0;
    const COMPLETION_MAX = 100;
  
    for (const evaluation of aggregated_evaluations) {
      let isAnomaly = false;
      const localFlags: string[] = [];
  
      const satisfactionScore = evaluation.satisfactionScore;
      const completionRate = evaluation.completionRate;
  
      if (
        satisfactionScore !== undefined &&
        (satisfactionScore < SATISFACTION_MIN ||
          satisfactionScore > SATISFACTION_MAX)
      ) {
        isAnomaly = true;
        localFlags.push('満足度スコア範囲外');
      }
  
      if (
        completionRate !== undefined &&
        (completionRate < COMPLETION_MIN || completionRate > COMPLETION_MAX)
      ) {
        isAnomaly = true;
        localFlags.push('完食度範囲外');
      }
  
      if (
        satisfactionScore !== undefined &&
        completionRate !== undefined &&
        satisfactionScore === SATISFACTION_MAX &&
        completionRate === COMPLETION_MAX &&
        evaluation.requestContent
      ) {
        const hasRequest =
          evaluation.requestContent &&
          typeof evaluation.requestContent === 'string' &&
          evaluation.requestContent.length > 0;
        if (hasRequest) {
          isAnomaly = true;
          localFlags.push('矛盾データ');
        }
      }
  
      if (!isAnomaly) {
        filtered_evaluations.push(evaluation);
      } else {
        anomalyFlags.push(...localFlags);
      }
    }
  
    const has_anomalies = anomalyFlags.length > 0;
  
    let trust_score = 1.0;
    if (aggregated_evaluations.length > 0) {
      const validCount = filtered_evaluations.length;
      const anomalyCount = aggregated_evaluations.length - validCount;
      trust_score = Math.max(
        0.85,
        1.0 - (anomalyCount / aggregated_evaluations.length) * 0.15
      );
    }
  
    return {
      has_anomalies,
      trust_score,
      filtered_evaluations,
      anomaly_flags: anomalyFlags.length > 0 ? anomalyFlags : [],
    };
  }
  return { detectAnomaliesInMealEvaluations };
})();
