/* AIVIC_FUNCTION_BUNDLE_START owner=detectAnomalousNutritionData exports=detectAnomalousNutritionData */
const __aivicBundle_29_detectAnomalousNutritionData = (() => {
  function detectAnomalousNutritionData(anomalousDataSet: EvaluationRecord[]): EvaluationRecord[] {
    // 異常値判定基準の定義
    const SATISFACTION_SCORE_MIN = 1;
    const SATISFACTION_SCORE_MAX = 5;
    const COMPLETION_RATE_MIN = 0;
    const COMPLETION_RATE_MAX = 100;
    const CALORIE_CONTENT_MIN = 0;
  
    // 単一レコードが異常値かどうかを判定する関数
    const isAnomalous = (record: EvaluationRecord): boolean => {
      // satisfactionScore が範囲外（1-5）
      if (
        record.satisfactionScore !== undefined &&
        (record.satisfactionScore < SATISFACTION_SCORE_MIN ||
          record.satisfactionScore > SATISFACTION_SCORE_MAX)
      ) {
        return true;
      }
  
      // completionRate が範囲外（0-100）
      if (
        record.completionRate !== undefined &&
        (record.completionRate < COMPLETION_RATE_MIN ||
          record.completionRate > COMPLETION_RATE_MAX)
      ) {
        return true;
      }
  
      // calorieContent が負数
      if (
        record.calorieContent !== undefined &&
        record.calorieContent < CALORIE_CONTENT_MIN
      ) {
        return true;
      }
  
      return false;
    };
  
    // すべてのレコードが異常値かどうかを確認
    const allAnomalous = anomalousDataSet.every(isAnomalous);
  
    // すべてが異常値の場合は空配列を返す
    if (allAnomalous) {
      return [];
    }
  
    // 1件でも正常値があれば、正常データのみをフィルタリングして返す
    return anomalousDataSet.filter((record) => !isAnomalous(record));
  }
  return { detectAnomalousNutritionData };
})();
export const detectAnomalousNutritionData: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_29_detectAnomalousNutritionData.detectAnomalousNutritionData as (...args: any[]) => any)(...args);
