/* AIVIC_FUNCTION_BUNDLE_START owner=selectRolloutSegments exports=selectRolloutSegments */
const __aivicBundle_32_selectRolloutSegments = (() => {
  function selectRolloutSegments(input: any): any {
    // Validation: segmentId
    if (!input.segmentId || input.segmentId === '') {
      throw new Error('セグメントIDが未定義または空です');
    }
  
    // Validation: ageGroup
    if (!input.ageGroup || input.ageGroup === '') {
      throw new Error('年代が未定義または空です');
    }
  
    // Validation: familySize
    if (input.familySize === null || input.familySize === undefined || input.familySize <= 0) {
      throw new Error('家族構成が無効です');
    }
  
    // Validation: adoptionRate
    if (typeof input.adoptionRate !== 'number' || input.adoptionRate < 0 || input.adoptionRate > 1) {
      throw new Error('採用率が範囲外です（0～1）');
    }
  
    // Validation: satisfactionScore
    if (typeof input.satisfactionScore !== 'number' || input.satisfactionScore < 0 || input.satisfactionScore > 100) {
      throw new Error('満足度スコアが範囲外です（0～100）');
    }
  
    // Validation: cookingTimeReduction
    if (typeof input.cookingTimeReduction !== 'number' || input.cookingTimeReduction < 0) {
      throw new Error('調理時間削減が負数です');
    }
  
    // Validation: hasRestriction
    if (typeof input.hasRestriction !== 'boolean') {
      throw new Error('制限フラグが不正な型です');
    }
  
    // Calculate rollout order based on adoption rate and satisfaction score
    const adoptionWeight = input.adoptionRate * 100;
    const satisfactionWeight = input.satisfactionScore;
    const combinedScore = (adoptionWeight * 0.6) + (satisfactionWeight * 0.4);
    
    // Normalize to 1-5 range
    const rolloutOrder = Math.ceil((combinedScore / 100) * 5);
    const normalizedRolloutOrder = Math.max(1, Math.min(5, rolloutOrder));
  
    // Calculate target user count based on family size and adoption rate
    const baseUserCount = Math.ceil(input.familySize * 10);
    const targetUserCount = Math.ceil(baseUserCount * input.adoptionRate);
  
    // Build result
    const result = {
      status: 'success',
      rolloutOrder: normalizedRolloutOrder,
      targetUserCount: Math.max(1, targetUserCount),
      rolloutExecuted: true,
      segmentId: input.segmentId,
      ageGroup: input.ageGroup,
      familySize: input.familySize,
      hasRestriction: input.hasRestriction,
      adoptionRate: input.adoptionRate,
      satisfactionScore: input.satisfactionScore,
      cookingTimeReduction: input.cookingTimeReduction,
    };
  
    return result;
  }
  return { selectRolloutSegments };
})();
export const selectRolloutSegments = __aivicBundle_32_selectRolloutSegments.selectRolloutSegments;
/* AIVIC_FUNCTION_BUNDLE_END owner=selectRolloutSegments */

