/* AIVIC_FUNCTION_BUNDLE_START owner=calculateImprovementDegree exports=calculateImprovementDegree */
const __aivicBundle_34_calculateImprovementDegree = (() => {
  function calculateImprovementDegree(
    previousWeekMetrics: {
      satisfactionScore: number;
      completionRate: number;
      rejectionRate: number;
      averageCookingTimeMinutes: number;
    },
    currentWeekMetrics: {
      satisfactionScore: number;
      completionRate: number;
      rejectionRate: number;
      averageCookingTimeMinutes: number;
    }
  ): {
    satisfactionScoreImprovement: number;
    completionRateImprovement: number;
    rejectionRateImprovement: number;
    cookingTimeReductionDegree: number;
    overallImprovementScore: number;
    improvementStatus: string;
    isImproved?: boolean;
    insufficientMetrics?: string[];
  } {
    // 満足度スコアの改善度を計算: (current - previous) / previous * 100
    const satisfactionScoreImprovement =
      ((currentWeekMetrics.satisfactionScore - previousWeekMetrics.satisfactionScore) /
        previousWeekMetrics.satisfactionScore) *
      100;
  
    // 完食度の改善度を計算: (current - previous) / previous * 100
    const completionRateImprovement =
      ((currentWeekMetrics.completionRate - previousWeekMetrics.completionRate) /
        previousWeekMetrics.completionRate) *
      100;
  
    // 却下率の改善度を計算: (previous - current) / previous * 100
    // 却下率は低いほど良いため、逆向きの計算
    const rejectionRateImprovement =
      ((previousWeekMetrics.rejectionRate - currentWeekMetrics.rejectionRate) /
        previousWeekMetrics.rejectionRate) *
      100;
  
    // 調理時間短縮度を計算: (previous - current) / previous * 100
    // 調理時間は短いほど良いため、逆向きの計算
    const cookingTimeReductionDegree =
      ((previousWeekMetrics.averageCookingTimeMinutes -
        currentWeekMetrics.averageCookingTimeMinutes) /
        previousWeekMetrics.averageCookingTimeMinutes) *
      100;
  
    // 総合改善度スコアを計算（各指標の平均値）
    const overallImprovementScore =
      (satisfactionScoreImprovement +
        completionRateImprovement +
        rejectionRateImprovement +
        cookingTimeReductionDegree) /
      4;
  
    // 最小閾値（5%）を超えているかで改善判定
    const minimumThreshold = 5;
    const isImproved =
      satisfactionScoreImprovement > minimumThreshold &&
      completionRateImprovement > minimumThreshold &&
      rejectionRateImprovement > minimumThreshold &&
      cookingTimeReductionDegree > minimumThreshold;
  
    // 改善状態を判定
    const improvementStatus = isImproved ? "改善あり" : "改善なし";
  
    // 改善が不足している指標を収集
    const insufficientMetrics: string[] = [];
    if (satisfactionScoreImprovement <= minimumThreshold) {
      insufficientMetrics.push("satisfaction");
    }
    if (completionRateImprovement <= minimumThreshold) {
      insufficientMetrics.push("completion");
    }
    if (rejectionRateImprovement <= minimumThreshold) {
      insufficientMetrics.push("rejection");
    }
    if (cookingTimeReductionDegree <= minimumThreshold) {
      insufficientMetrics.push("cookingTime");
    }
  
    return {
      satisfactionScoreImprovement,
      completionRateImprovement,
      rejectionRateImprovement,
      cookingTimeReductionDegree,
      overallImprovementScore,
      improvementStatus,
      isImproved,
      insufficientMetrics: insufficientMetrics.length > 0 ? insufficientMetrics : [],
    };
  }
  return { calculateImprovementDegree };
})();
export const calculateImprovementDegree = __aivicBundle_34_calculateImprovementDegree.calculateImprovementDegree;
