    // Collect all dietary restrictions
    const restrictionSet = new Set<string>();
    dietaryRestrictions.forEach(info => {
      restrictionSet.add(info.restriction);
    });
    const restrictions = Array.from(restrictionSet);
  
    // Generate initial meal plans based on constraints
