const __aivicBundle_48_prioritizeNutrientDeficiencyItems = (() => {
  function prioritizeNutrientDeficiencyItems(
    nutrientDeficiencies: Array<{
      nutrientId: string;
      deficiencyAmount: number;
      improvementEffectScore: number;
    }>,
    familyMemberPreferences: Array<{
      familyMemberId: string;
      preferenceScore: number;
    }>,
    preferenceRiskCoefficient: number | null | undefined
  ): Array<{
    nutrientId: string;
    priorityScore: number;
  }> {
    // Validate preferenceRiskCoefficient
    if (
      preferenceRiskCoefficient === null ||
      preferenceRiskCoefficient === undefined
    ) {
      throw new Error("嗜好リスク係数が無効です");
    }
  
    if (preferenceRiskCoefficient < 0 || preferenceRiskCoefficient > 1.0) {
      throw new Error("嗜好リスク係数は0から1.0の範囲内である必要があります");
    }
  
    // Calculate average preference score from family members
    const averagePreferenceScore =
      familyMemberPreferences.length > 0
        ? familyMemberPreferences.reduce(
            (sum, member) => sum + member.preferenceScore,
            0
          ) / familyMemberPreferences.length
        : 0.5;
  
    // Calculate priority score for each nutrient deficiency
    const prioritizedItems = nutrientDeficiencies.map((deficiency) => {
      // Priority score = deficiency amount × improvement effect score × preference factor
      // Preference factor incorporates average preference score and risk coefficient
      const preferenceFactor =
        averagePreferenceScore * (1 - preferenceRiskCoefficient) +
        preferenceRiskCoefficient;
  
      const priorityScore =
        deficiency.deficiencyAmount *
        deficiency.improvementEffectScore *
        preferenceFactor;
  
      return {
        nutrientId: deficiency.nutrientId,
        priorityScore,
      };
    });
  
    // Sort by priority score in descending order
    prioritizedItems.sort((a, b) => b.priorityScore - a.priorityScore);
  
    return prioritizedItems;
  }
  return { prioritizeNutrientDeficiencyItems };
})();
