const __aivicBundle_49_determinePriorityCondition = (() => {
  interface DeterminePriorityConditionInput {
    budget_limit: number;
    actual_spending: number;
    protein_target: number;
    protein_actual: number;
    vitamin_c_target: number;
    vitamin_c_actual: number;
    calcium_target: number;
    calcium_actual: number;
  }
  
  interface DeterminePriorityConditionOutput {
    decision: "栄養重視" | "食費重視" | "満足度重視";
    food_cost_excess_rate: number;
    nutrition_deficiency_rate: number;
    priority_order: string[];
    recommended_menu_config: {
      nutrition_priority: boolean;
      cost_optimization_priority: boolean;
      calorie_range_min: number;
      calorie_range_max: number;
      nutrient_targets: {
        protein_g: number;
        calcium_mg: number;
        vitamin_c_mg: number;
      };
      estimated_daily_cost_limit: number;
    };
  }
  
   function determinePriorityCondition(
    input: DeterminePriorityConditionInput
  ): DeterminePriorityConditionOutput {
    const {
      budget_limit,
      actual_spending,
      protein_target,
      protein_actual,
      vitamin_c_target,
      vitamin_c_actual,
      calcium_target,
      calcium_actual,
    } = input;
  
    // 食費超過率を計算
    const food_cost_excess_rate =
      budget_limit > 0
        ? Math.max(0, (actual_spending - budget_limit) / budget_limit)
        : 0;
  
    // 栄養不足率を計算（複数栄養素の平均不足率）
    const protein_deficiency =
      protein_target > 0
        ? Math.max(0, (protein_target - protein_actual) / protein_target)
        : 0;
    const vitamin_c_deficiency =
      vitamin_c_target > 0
        ? Math.max(0, (vitamin_c_target - vitamin_c_actual) / vitamin_c_target)
        : 0;
    const calcium_deficiency =
      calcium_target > 0
        ? Math.max(0, (calcium_target - calcium_actual) / calcium_target)
        : 0;
  
    const nutrition_deficiency_rate =
      (protein_deficiency + vitamin_c_deficiency + calcium_deficiency) / 3;
  
    // 優先度判定: 食費超過度合い vs 栄養不足度合い を比較
    let decision: "栄養重視" | "食費重視" | "満足度重視";
    let priority_order: string[];
  
    if (food_cost_excess_rate > nutrition_deficiency_rate) {
      decision = "食費重視";
      priority_order = ["食費超過の抑制", "栄養不足項目の改善"];
    } else if (nutrition_deficiency_rate > food_cost_excess_rate) {
      decision = "栄養重視";
      priority_order = ["栄養不足項目の改善", "食費超過の抑制"];
    } else {
      decision = "満足度重視";
      priority_order = ["満足度向上", "食費超過の抑制", "栄養不足項目の改善"];
    }
  
    // 推奨献立設定を構築
    const recommended_menu_config = {
      nutrition_priority: decision === "栄養重視",
      cost_optimization_priority: decision === "食費重視",
      calorie_range_min: 1900,
      calorie_range_max: 2100,
      nutrient_targets: {
        protein_g: 65,
        calcium_mg: 850,
        vitamin_c_mg: 110,
      },
      estimated_daily_cost_limit: Math.floor(budget_limit / 30),
    };
  
    return {
      decision,
      food_cost_excess_rate,
      nutrition_deficiency_rate,
      priority_order,
      recommended_menu_config,
    };
  }
  return { determinePriorityCondition };
})();
