const __aivicBundle_51_calculateBudgetOverage = (() => {
  function calculateBudgetOverage(input: {
    budget: number;
    actual: number;
  }): number {
    const { budget, actual } = input;
  
    if (budget <= 0) {
      throw new Error("予算は0より大きい値である必要があります");
    }
  
    if (actual < 0) {
      throw new Error("実績は0以上である必要があります");
    }
  
    const overageAmount = actual - budget;
    return Math.max(0, overageAmount);
  }
  return { calculateBudgetOverage };
})();
