/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMonthlyCostTotal exports=calculateMonthlyCostTotal */
const __aivicBundle_55_calculateMonthlyCostTotal = (() => {
  interface CalculateMonthlyCostTotalInput {
    userId: string;
    year: number;
    month: number;
    purchaseRecords: Array<{
      id: string;
      userId: string;
      purchaseDate: string;
      amount: number;
    }>;
  }
  
  interface CalculateMonthlyCostTotalOutput {
    totalCost: number;
    currencyCode: string;
    hasData: boolean;
    month: number;
    year: number;
  }
  
   function calculateMonthlyCostTotal(
    input: CalculateMonthlyCostTotalInput
  ): CalculateMonthlyCostTotalOutput {
    const { userId, year, month, purchaseRecords } = input;
  
    // Validation
    if (!userId || userId.trim() === "") {
      throw new Error("ユーザーIDが無効です");
    }
  
    if (month < 1 || month > 12) {
      throw new Error("月が無効です（1-12の範囲で指定してください）");
    }
  
    if (year < 1901 || year > 9999) {
      throw new Error("年が無効です（1901年以降を指定してください）");
    }
  
    // Filter records for the specified month and year, and for the specified user
    const filteredRecords = purchaseRecords.filter((record) => {
      if (record.userId !== userId) {
        return false;
      }
  
      const recordDate = new Date(record.purchaseDate);
      const recordYear = recordDate.getFullYear();
      const recordMonth = recordDate.getMonth() + 1;
  
      return recordYear === year && recordMonth === month;
    });
  
    // Calculate total cost
    const totalCost = filteredRecords.reduce((sum, record) => {
      return sum + record.amount;
    }, 0);
  
    return {
      totalCost,
      currencyCode: "JPY",
      hasData: filteredRecords.length > 0,
      month,
      year,
    };
  }
  return { calculateMonthlyCostTotal };
})();
