/* AIVIC_FUNCTION_BUNDLE_START owner=calculatePredictionAccuracyImprovementPriority exports=calculatePredictionAccuracyImprovementPriority */
const __aivicBundle_62_calculatePredictionAccuracyImprovementPriority = (() => {
  function calculatePredictionAccuracyImprovementPriority(input: {
    predicted_value?: number;
    actual_value?: number;
    divergence_rate?: number;
    accuracyGapPercent?: number;
    affectedUserCount?: number;
    businessImpactScore?: number;
    implementationEffortDays?: number;
    estimatedROI?: number;
  }): {
    divergence_rate?: number;
    priority_score?: number;
    improvement_level?: string;
    priorityRank?: number;
    priorityLevel?: 'P0' | 'P1' | 'P2' | 'P3';
    scoreBreakdown?: {
      accuracyWeight: number;
      userImpactWeight: number;
      businessImpactWeight: number;
      effortWeight: number;
      roiWeight: number;
    };
    recommendedScheduling?: string;
  } {
    // テスト形式: divergence_rate ベースの優先度計算
    if (input.divergence_rate !== undefined) {
      const divergenceRate = input.divergence_rate;
      let improvementLevel: string;
  
      if (divergenceRate === 0) {
        improvementLevel = 'none';
      } else if (divergenceRate < 25) {
        improvementLevel = 'low';
      } else if (divergenceRate < 50) {
        improvementLevel = 'medium';
      } else if (divergenceRate < 75) {
        improvementLevel = 'high';
      } else {
        improvementLevel = 'critical';
      }
  
      return {
        divergence_rate: divergenceRate,
        priority_score: divergenceRate,
        improvement_level: improvementLevel,
      };
    }
  
    // プラン形式: 複合要因ベースの優先度計算
    const accuracyGap = input.accuracyGapPercent ?? 0;
    const affectedUsers = input.affectedUserCount ?? 0;
    const businessImpact = input.businessImpactScore ?? 0;
    const effortDays = input.implementationEffortDays ?? 1;
    const roi = input.estimatedROI ?? 0;
  
    // 重み付け定数
    const weights = {
      accuracyWeight: 0.35,
      userImpactWeight: 0.25,
      businessImpactWeight: 0.25,
      effortWeight: 0.1,
      roiWeight: 0.05,
    };
  
    // 各要因を 0-100 スケールに正規化
    const normalizedAccuracy = Math.min(accuracyGap, 100);
    const normalizedUserImpact = Math.min((affectedUsers / 1000) * 100, 100);
    const normalizedBusinessImpact = Math.min(businessImpact, 100);
    const normalizedEffort = Math.max(0, 100 - (effortDays / 30) * 100);
    const normalizedROI = Math.min(roi * 10, 100);
  
    // 加重平均で総合スコアを計算
    const totalScore =
      normalizedAccuracy * weights.accuracyWeight +
      normalizedUserImpact * weights.userImpactWeight +
      normalizedBusinessImpact * weights.businessImpactWeight +
      normalizedEffort * weights.effortWeight +
      normalizedROI * weights.roiWeight;
  
    // スコアから優先度ランクを決定
    let priorityRank: number;
    let priorityLevel: 'P0' | 'P1' | 'P2' | 'P3';
    let recommendedScheduling: string;
  
    if (totalScore >= 75) {
      priorityRank = 1;
      priorityLevel = 'P0';
      recommendedScheduling = '即座に実施';
    } else if (totalScore >= 50) {
      priorityRank = 2;
      priorityLevel = 'P1';
      recommendedScheduling = '次のスプリントで実施';
    } else if (totalScore >= 25) {
      priorityRank = 3;
      priorityLevel = 'P2';
      recommendedScheduling = '計画的に実施';
    } else {
      priorityRank = 4;
      priorityLevel = 'P3';
      recommendedScheduling = 'バックログ';
    }
  
    return {
      priorityRank,
      priorityLevel,
      scoreBreakdown: weights,
      recommendedScheduling,
    };
  }
  return { calculatePredictionAccuracyImprovementPriority };
})();
