/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateNutritionLogicWithTiebreaker exports=evaluateNutritionLogicWithTiebreaker */
const __aivicBundle_84_evaluateNutritionLogicWithTiebreaker = (() => {
  function evaluateNutritionLogicWithTiebreaker(
    input: any
  ): {
    rankedCandidates: Array<{
      mealPlanId: string;
      priorityScore: number;
      nutritionBalance?: number;
      costEfficiency?: number;
      cookingDifficulty?: number;
    }>;
    tieBreakingRuleApplied: boolean;
  } {
    // Input validation
    if (!Array.isArray(input)) {
      return {
        rankedCandidates: [],
        tieBreakingRuleApplied: false,
      };
    }
  
    if (input.length === 0) {
      return {
        rankedCandidates: [],
        tieBreakingRuleApplied: false,
      };
    }
  
    // Group candidates by priorityScore
    const groupedByPriority = new Map<
      number,
      Array<{
        mealPlanId: string;
        priorityScore: number;
        nutritionBalance?: number;
        costEfficiency?: number;
        cookingDifficulty?: number;
      }>
    >();
  
    for (const candidate of input) {
      const priority = candidate.priorityScore;
      if (!groupedByPriority.has(priority)) {
        groupedByPriority.set(priority, []);
      }
      groupedByPriority.get(priority)!.push(candidate);
    }
  
    // Sort priority groups in descending order
    const sortedPriorities = Array.from(groupedByPriority.keys()).sort(
      (a, b) => b - a
    );
  
    const rankedCandidates: Array<{
      mealPlanId: string;
      priorityScore: number;
      nutritionBalance?: number;
      costEfficiency?: number;
      cookingDifficulty?: number;
    }> = [];
  
    let tieBreakingRuleApplied = false;
  
    // Process each priority group
    for (const priority of sortedPriorities) {
      const group = groupedByPriority.get(priority)!;
  
      if (group.length === 1) {
        rankedCandidates.push(group[0]);
      } else {
        // Apply tiebreaking logic
        tieBreakingRuleApplied = true;
  
        // First tiebreaker: nutritionBalance (descending)
        let sortedGroup = [...group].sort(
          (a, b) => (b.nutritionBalance ?? 0) - (a.nutritionBalance ?? 0)
        );
  
        // Check if all have same nutritionBalance
        const allSameNutrition = sortedGroup.every(
          (c) => c.nutritionBalance === sortedGroup[0].nutritionBalance
        );
  
        if (allSameNutrition) {
          // Second tiebreaker: costEfficiency (descending)
          sortedGroup = sortedGroup.sort(
            (a, b) => (b.costEfficiency ?? 0) - (a.costEfficiency ?? 0)
          );
  
          // Check if all have same costEfficiency
          const allSameCost = sortedGroup.every(
            (c) => c.costEfficiency === sortedGroup[0].costEfficiency
          );
  
          if (allSameCost) {
            // Third tiebreaker: cookingDifficulty (ascending - lower is better)
            sortedGroup = sortedGroup.sort(
              (a, b) => (a.cookingDifficulty ?? 0) - (b.cookingDifficulty ?? 0)
            );
          }
        }
  
        rankedCandidates.push(...sortedGroup);
      }
    }
  
    return {
      rankedCandidates,
      tieBreakingRuleApplied,
    };
  }
  return { evaluateNutritionLogicWithTiebreaker };
})();
