    const success_rate_improvement = post_improvement_success_rate - pre_improvement_success_rate;
    const normalized_success_improvement = Math.max(0, success_rate_improvement) * 0.5;
    const normalized_cooking_time = Math.min(cooking_time_reduction_degree, 100) * 0.3;
    const normalized_satisfaction = Math.min(user_satisfaction_score, 100) * 0.2;
  
