/* AIVIC_FUNCTION_BUNDLE_START owner=calculateAlgorithmImprovementEffect exports=calculateAlgorithmImprovementEffect */
const __aivicBundle_88_calculateAlgorithmImprovementEffect = (() => {
  function calculateAlgorithmImprovementEffect(input: {
    preAlgorithmScore?: number;
    postAlgorithmScore?: number;
    baselineMetrics?: {
      successRate: number;
      cookingTimeMinutes: number;
      satisfactionScore: number;
      userCount: number;
    };
    improvedMetrics?: {
      successRate: number;
      cookingTimeMinutes: number;
      satisfactionScore: number;
      userCount: number;
    };
    weights?: {
      successRateWeight: number;
      cookingTimeWeight: number;
      satisfactionWeight: number;
    };
  }): {
    successRateImprovement?: number;
    cookingTimeImprovement?: number;
    satisfactionImprovement?: number;
    overallImprovementScore?: number;
    isSignificant?: boolean;
    improvementPercentage: number;
    status: string;
    hasError: boolean;
    errorMessage: null | string;
  } {
    // Handle preAlgorithmScore / postAlgorithmScore case (test case)
    if (
      input.preAlgorithmScore !== undefined &&
      input.postAlgorithmScore !== undefined
    ) {
      const preScore = input.preAlgorithmScore;
      const postScore = input.postAlgorithmScore;
  
      const improvementPercentage =
        preScore === 0 ? 0 : ((postScore - preScore) / preScore) * 100;
  
      const status =
        improvementPercentage === 0
          ? '改善なし'
          : improvementPercentage > 0
            ? '改善あり'
            : '悪化';
  
      return {
        improvementPercentage,
        status,
        hasError: false,
        errorMessage: null,
      };
    }
  
    // Handle baselineMetrics / improvedMetrics case (plan case)
    if (input.baselineMetrics && input.improvedMetrics) {
      const baseline = input.baselineMetrics;
      const improved = input.improvedMetrics;
  
      // Default weights if not provided
      const weights = input.weights || {
        successRateWeight: 0.4,
        cookingTimeWeight: 0.3,
        satisfactionWeight: 0.3,
      };
  
      // Calculate individual improvements (as percentages)
      const successRateImprovement =
        baseline.successRate === 0
          ? 0
          : ((improved.successRate - baseline.successRate) /
              baseline.successRate) *
            100;
  
      const cookingTimeImprovement =
        baseline.cookingTimeMinutes === 0
          ? 0
          : ((baseline.cookingTimeMinutes - improved.cookingTimeMinutes) /
              baseline.cookingTimeMinutes) *
            100;
  
      const satisfactionImprovement =
        baseline.satisfactionScore === 0
          ? 0
          : ((improved.satisfactionScore - baseline.satisfactionScore) /
              baseline.satisfactionScore) *
            100;
  
      // Calculate weighted overall improvement score
      const overallImprovementScore =
        successRateImprovement * weights.successRateWeight +
        cookingTimeImprovement * weights.cookingTimeWeight +
        satisfactionImprovement * weights.satisfactionWeight;
  
      // Determine significance (>= 10 is significant)
      const isSignificant = overallImprovementScore >= 10;
  
      return {
        successRateImprovement,
        cookingTimeImprovement,
        satisfactionImprovement,
        overallImprovementScore,
        isSignificant,
        improvementPercentage: overallImprovementScore,
        status:
          overallImprovementScore === 0
            ? '改善なし'
            : overallImprovementScore > 0
              ? '改善あり'
              : '悪化',
        hasError: false,
        errorMessage: null,
      };
    }
  
    // Default case when neither input shape is provided
    return {
      improvementPercentage: 0,
      status: '改善なし',
      hasError: false,
      errorMessage: null,
    };
  }
  return { calculateAlgorithmImprovementEffect };
})();
export const calculateAlgorithmImprovementEffect = __aivicBundle_88_calculateAlgorithmImprovementEffect.calculateAlgorithmImprovementEffect;
