/* AIVIC_FUNCTION_BUNDLE_START owner=notifyDevelopmentTeamOnImprovementProposal exports=notifyDevelopmentTeamOnImprovementProposal */
const __aivicBundle_90_notifyDevelopmentTeamOnImprovementProposal = (() => {
  function notifyDevelopmentTeamOnImprovementProposal(
    proposal: {
      proposalId: string;
      title?: string;
      description?: string;
      proposedBy?: string;
      createdAt?: Date;
      status?: string;
      priority?: string;
      improvementType?: string;
      estimatedAccuracyGain?: number;
      affectedUserCount?: number;
      implementationComplexity?: number;
      expectedROI?: number;
      priorityScore?: number;
      recommendedAction?: string;
    },
    config: {
      developmentTeamMembers?: Array<{ id: string; name: string; capacity: number }>;
      notificationChannels: string[];
      priority?: string;
      teamSize?: number;
      currentCapacity?: number;
    }
  ): {
    notificationDelivered: boolean;
    assignedDeveloper: string | null;
    estimatedStartDate: string;
    notificationChannelsUsed: string[];
  } {
    if (proposal["proposalId"] === undefined || proposal["proposalId"] === null) { throw new Error("proposalId is required"); }
    // Validate required proposalId
    if (proposal.proposalId === undefined || proposal.proposalId === null || String(proposal.proposalId).trim() === "") {
      throw new Error("proposalId is required");
    }
  
    // Validate required team members or team configuration
    if (
      (!config.developmentTeamMembers || config.developmentTeamMembers.length === 0) &&
      config.teamSize === undefined &&
      config.currentCapacity === undefined
    ) {
      throw new Error("通知先メンバーが設定されていません");
    }
  
    // Determine available developers
    let availableDeveloperCount = 0;
    let assignedDeveloper: string | null = null;
  
    if (config.developmentTeamMembers && config.developmentTeamMembers.length > 0) {
      // Use provided team members
      const availableMembers = config.developmentTeamMembers.filter(
        (member) => member.capacity > 0
      );
      availableDeveloperCount = availableMembers.length;
      if (availableMembers.length > 0) {
        assignedDeveloper = availableMembers[0].id;
      }
    } else if (
      config.teamSize !== undefined &&
      config.currentCapacity !== undefined
    ) {
      // Use team size and capacity
      availableDeveloperCount = config.teamSize - config.currentCapacity;
      if (availableDeveloperCount > 0) {
        // Generate deterministic developer ID based on proposalId hash
        const proposalIdHash = proposal.proposalId
          .split("")
          .reduce((acc, char) => acc + char.charCodeAt(0), 0);
        const devNumber = (proposalIdHash % 1000).toString().padStart(3, "0");
        assignedDeveloper = `dev-${devNumber}`;
      }
    }
  
    // Calculate estimated start date based on priority and capacity
    const now = new Date();
    let daysToAdd = 7; // Default: 1 week
  
    if (config.priority === "urgent" || proposal.priority === "high") {
      daysToAdd = 5;
    } else if (config.priority === "high" || proposal.priorityScore !== undefined) {
      if (proposal.priorityScore !== undefined && proposal.priorityScore >= 70) {
        daysToAdd = 5;
      } else {
        daysToAdd = 10;
      }
    }
  
    // Adjust based on current capacity
    if (config.currentCapacity !== undefined && config.teamSize !== undefined) {
      if (config.currentCapacity === config.teamSize) {
        daysToAdd += 10; // Team fully occupied
      }
    }
  
    const estimatedStartDate = new Date(now.getTime() + daysToAdd * 24 * 60 * 60 * 1000);
    const estimatedStartDateStr = estimatedStartDate.toISOString().split("T")[0];
  
    // Validate notification channels
    const validChannels = ["email", "slack", "teams", "sms"];
    const usedChannels = (config.notificationChannels || []).filter((channel) =>
      validChannels.includes(channel.toLowerCase())
    );
  
    return {
      notificationDelivered: true,
      assignedDeveloper,
      estimatedStartDate: estimatedStartDateStr,
      notificationChannelsUsed: usedChannels,
    };
  }
  return { notifyDevelopmentTeamOnImprovementProposal };
})();
