  function detectAndCorrectDataAnomalies(input: any): any {
    // Handle both array input and object with dataRecords property
    const records = Array.isArray(input) ? input : input?.dataRecords || [];
    
    if (records.length === 0) {
      return {
        detected_anomalies: [],
        corrected_data: [],
        correction_log: [],
        data_quality_score: 100,
        summary: {
          total_records: 0,
          anomaly_count: 0,
          corrected_count: 0,
          corrected_fields: [],
        },
        cleanedRecords: [],
        anomaliesDetected: 0,
        correctionApplied: 'none',
        dataQualityScore: 100,
      };
    }
  
    const detected_anomalies: any[] = [];
    const corrected_data: any[] = [];
    const correction_log: any[] = [];
    const corrected_fields_set = new Set<string>();
  
    // Define field validation rules
    const fieldRules: Record<string, { type: string; min?: number; max?: number; required?: boolean }> = {
      satisfaction_score: { type: 'number', min: 1, max: 5, required: false },
      completion_rate: { type: 'number', min: 0, max: 1, required: false },
      request_text: { type: 'string', required: false },
      timestamp: { type: 'string', required: false },
    };
  
    // Process each record
    records.forEach((record: any, index: number) => {
      const recordId = record.feedback_id || record.id || `record_${index}`;
      const correctedRecord = { ...record };
      const recordCorrections: any[] = [];
  
      // Check each field for anomalies
      Object.entries(fieldRules).forEach(([field, rule]) => {
        const value = record[field];
  
        // Check for missing values
        if (value === null || value === undefined || value === '') {
          if (field === 'request_text' && value === '') {
            // Empty string for request_text is acceptable
            return;
          }
  
          detected_anomalies.push({
            feedback_id: recordId,
            field,
            anomaly_type: 'missing_value',
            detected_value: value,
          });
  
          corrected_fields_set.add(field);
  
          // Apply correction based on field type
          let correctedValue: any;
          if (field === 'satisfaction_score') {
            correctedValue = 3; // Default middle value
          } else if (field === 'completion_rate') {
            correctedValue = 0.5; // Default middle value
          } else if (field === 'request_text') {
            correctedValue = '';
          } else if (field === 'timestamp') {
            correctedValue = new Date().toISOString();
          }
  
          recordCorrections.push({
            field,
            original_value: value,
            corrected_value: correctedValue,
            reason: 'missing_value - default applied',
          });
  
          correctedRecord[field] = correctedValue;
        } else if (rule.type === 'number' && typeof value === 'number') {
          // Check for out-of-range values
          if (rule.min !== undefined && value < rule.min) {
            detected_anomalies.push({
              feedback_id: recordId,
              field,
              anomaly_type: 'out_of_range',
              detected_value: value,
            });
  
            corrected_fields_set.add(field);
  
            const correctedValue = rule.min;
            recordCorrections.push({
              field,
              original_value: value,
              corrected_value: correctedValue,
              reason: `out_of_range - clamped to min ${rule.min}`,
            });
  
            correctedRecord[field] = correctedValue;
          } else if (rule.max !== undefined && value > rule.max) {
            detected_anomalies.push({
              feedback_id: recordId,
              field,
              anomaly_type: 'out_of_range',
              detected_value: value,
            });
  
            corrected_fields_set.add(field);
  
            const correctedValue = rule.max;
            recordCorrections.push({
              field,
              original_value: value,
              corrected_value: correctedValue,
              reason: `out_of_range - clamped to max ${rule.max}`,
            });
  
            correctedRecord[field] = correctedValue;
          }
        } else if (field === 'timestamp' && typeof value === 'string') {
          // Validate timestamp format
          const date = new Date(value);
          if (isNaN(date.getTime())) {
            detected_anomalies.push({
              feedback_id: recordId,
              field,
              anomaly_type: 'invalid_format',
              detected_value: value,
            });
  
            corrected_fields_set.add(field);
  
            const correctedValue = new Date().toISOString();
            recordCorrections.push({
              field,
              original_value: value,
              corrected_value: correctedValue,
              reason: 'invalid_format - replaced with current timestamp',
            });
  
            correctedRecord[field] = correctedValue;
          }
        }
      });
  
      corrected_data.push(correctedRecord);
  
      if (recordCorrections.length > 0) {
        correction_log.push({
          feedback_id: recordId,
          corrections: recordCorrections,
        });
      }
    });
  
    // Calculate data quality score (0-100)
    const totalFields = records.length * Object.keys(fieldRules).length;
    const anomalousFields = detected_anomalies.length;
    const dataQualityScore = Math.max(0, Math.min(100, 100 - (anomalousFields / totalFields) * 100));
  
    const summary = {
      total_records: records.length,
      anomaly_count: detected_anomalies.length,
      corrected_count: correction_log.length,
      corrected_fields: Array.from(corrected_fields_set),
    };
  
    // Build cleaned records for plan-based interface
    const cleanedRecords = corrected_data.map((record: any) => ({
      id: record.id || record.feedback_id,
      value: record.satisfaction_score,
      timestamp: record.timestamp,
    }));
  
    return {
      detected_anomalies,
      corrected_data,
      correction_log,
      data_quality_score: dataQualityScore,
      summary,
      cleanedRecords,
      anomaliesDetected: detected_anomalies.length,
      correctionApplied: detected_anomalies.length > 0 ? 'mixed' : 'none',
      dataQualityScore,
    };
  }
  return { detectAndCorrectDataAnomalies };
