/* AIVIC_FUNCTION_BUNDLE_START owner=detectAndExcludeAnomalies exports=detectAndExcludeAnomalies */
const __aivicBundle_92_detectAndExcludeAnomalies = (() => {
  function detectAndExcludeAnomalies(input: any): any {
    const records = Array.isArray(input) ? input : input.evaluationRecords || [];
    
    const validRecords: any[] = [];
    const excludedRecords: any[] = [];
    const exclusionReasons: Record<string, number> = {};
  
    // Detect missing values and anomalies
    for (const record of records) {
      const issues: Array<{ reason: string; field: string }> = [];
  
      // Check for missing values
      if (record.satisfaction_score === null || record.satisfaction_score === undefined) {
        issues.push({ reason: '欠損値', field: 'satisfaction_score' });
      }
      if (record.meal_completion_rate === null || record.meal_completion_rate === undefined) {
        issues.push({ reason: '欠損値', field: 'meal_completion_rate' });
      }
  
      // Check for anomalies (satisfaction_score should be 1-5, completion_rate should be 0-100)
      if (
        record.satisfaction_score !== null &&
        record.satisfaction_score !== undefined &&
        (record.satisfaction_score < 1 || record.satisfaction_score > 5)
      ) {
        issues.push({ reason: '異常値', field: 'satisfaction_score' });
      }
      if (
        record.meal_completion_rate !== null &&
        record.meal_completion_rate !== undefined &&
        (record.meal_completion_rate < 0 || record.meal_completion_rate > 100)
      ) {
        issues.push({ reason: '異常値', field: 'meal_completion_rate' });
      }
  
      if (issues.length > 0) {
        // Exclude record with first issue
        const issue = issues[0];
        excludedRecords.push({
          user_id: record.user_id,
          reason: issue.reason,
          field: issue.field,
        });
        exclusionReasons[issue.reason] = (exclusionReasons[issue.reason] || 0) + 1;
      } else {
        validRecords.push(record);
      }
    }
  
    const analysisTimestamp = new Date().toISOString();
  
    return {
      valid_data: validRecords,
      excluded_data: excludedRecords,
      exclusion_summary: {
        total_records: records.length,
        valid_records: validRecords.length,
        excluded_records: excludedRecords.length,
        exclusion_reasons: exclusionReasons,
      },
      analysis_log: {
        execution_timestamp: analysisTimestamp,
        status: 'completed',
        message: `分析完了: ${excludedRecords.length}件の欠損値・異常値を検出`,
      },
    };
  }
  return { detectAndExcludeAnomalies };
})();
export const detectAndExcludeAnomalies = __aivicBundle_92_detectAndExcludeAnomalies.detectAndExcludeAnomalies;
