const __aivicBundle_94_detectAndCorrectMissingValues = (() => {
  interface DetectAndCorrectMissingValuesInput {
    userId: string;
    familyMembers: Array<{
      memberId: string;
      name: string;
      age: number;
      satisfactionScore: number | null;
    }>;
    mealRecords: Array<{
      recordId: string;
      mealDate: string;
      dishName: string;
      completionRate: number | null;
    }>;
    nutritionData: Array<{
      nutrientId: string;
      nutrientName: string;
      actualValue: number;
      targetValue: number;
    }>;
  }
  
  interface DetectAndCorrectMissingValuesOutput {
    missingRate: number;
    shouldCorrect: boolean;
    correctionApplied: boolean;
    correctionLog: string;
    correctedData: {
      userId: string;
      familyMembers: Array<{
        memberId: string;
        name: string;
        age: number;
        satisfactionScore: number;
      }>;
      mealRecords: Array<{
        recordId: string;
        mealDate: string;
        dishName: string;
        completionRate: number | null;
      }>;
      nutritionData: Array<{
        nutrientId: string;
        nutrientName: string;
        actualValue: number;
        targetValue: number;
      }>;
    };
  }
  
   function detectAndCorrectMissingValues(
    input: DetectAndCorrectMissingValuesInput,
    threshold: number
  ): DetectAndCorrectMissingValuesOutput {
    // Count total nullable fields and missing values
    const familyMembersCount = input.familyMembers.length;
    const mealRecordsCount = input.mealRecords.length;
    const totalNullableFields = familyMembersCount + mealRecordsCount;
  
    let missingCount = 0;
  
    // Count missing satisfactionScore in familyMembers
    for (const member of input.familyMembers) {
      if (member.satisfactionScore === null) {
        missingCount++;
      }
    }
  
    // Count missing completionRate in mealRecords
    for (const record of input.mealRecords) {
      if (record.completionRate === null) {
        missingCount++;
      }
    }
  
    const missingRate = totalNullableFields > 0 ? missingCount / totalNullableFields : 0;
    const shouldCorrect = missingRate >= threshold;
  
    let correctionLog = '';
    let correctedFamilyMembers = input.familyMembers.map(m => ({ ...m }));
    let correctedMealRecords = input.mealRecords.map(r => ({ ...r }));
  
    if (shouldCorrect) {
      correctionLog = '補正対象';
  
      // Calculate mean satisfactionScore from non-null values
      const validScores = input.familyMembers
        .filter(m => m.satisfactionScore !== null)
        .map(m => m.satisfactionScore as number);
      const meanScore = validScores.length > 0 ? validScores.reduce((a, b) => a + b, 0) / validScores.length : 0;
  
      // Correct familyMembers
      correctedFamilyMembers = input.familyMembers.map(m => {
        if (m.satisfactionScore === null) {
          return {
            ...m,
            satisfactionScore: meanScore,
          };
        }
        return m;
      });
  
      // Calculate mean completionRate from non-null values
      const validRates = input.mealRecords
        .filter(r => r.completionRate !== null)
        .map(r => r.completionRate as number);
      const meanRate = validRates.length > 0 ? validRates.reduce((a, b) => a + b, 0) / validRates.length : 0;
  
      // Correct mealRecords
      correctedMealRecords = input.mealRecords.map(r => {
        if (r.completionRate === null) {
          return {
            ...r,
            completionRate: meanRate,
          };
        }
        return r;
      });
    } else {
      correctionLog = '補正対象外';
    }
  
    return {
      missingRate: Math.round(missingRate * 100) / 100,
      shouldCorrect,
      correctionApplied: shouldCorrect,
      correctionLog,
      correctedData: {
        userId: input.userId,
        familyMembers: correctedFamilyMembers,
        mealRecords: correctedMealRecords,
        nutritionData: input.nutritionData,
      },
    };
  }
  return { detectAndCorrectMissingValues };
})();
