/* AIVIC_FUNCTION_BUNDLE_START owner=calculateCookingTimeAchievementBySegment exports=calculateCookingTimeAchievementBySegment */
const __aivicBundle_100_calculateCookingTimeAchievementBySegment = (() => {
  function calculateCookingTimeAchievementBySegment(
    segments: Array<{
      segmentId: string;
      segmentName: string;
      targetCookingTime: number;
      actualCookingTime: number;
    }>
  ): Array<{
    segmentId: string;
    segmentName: string;
    targetCookingTime: number;
    actualCookingTime: number;
    timeDifference: number;
    achievementPercentage: number;
  }> {
    if (!segments || segments.length === 0) {
      throw new Error('セグメント配列が空です');
    }
  
    return segments.map((segment) => {
      if (segment.targetCookingTime === 0) {
        throw new Error('目標調理時間が0以下です');
      }
  
      if (segment.actualCookingTime < 0) {
        throw new Error('実績調理時間が負の値です');
      }
  
      const timeDifference = segment.targetCookingTime - segment.actualCookingTime;
      const achievementPercentage = Number(
        ((timeDifference / segment.targetCookingTime) * 100).toFixed(1)
      );
  
      return {
        segmentId: segment.segmentId,
        segmentName: segment.segmentName,
        targetCookingTime: segment.targetCookingTime,
        actualCookingTime: segment.actualCookingTime,
        timeDifference,
        achievementPercentage,
      };
    });
  }
  return { calculateCookingTimeAchievementBySegment };
})();
