/* AIVIC_FUNCTION_BUNDLE_START owner=calculateCookingTimeAchievementDegree exports=calculateCookingTimeAchievementDegree */
const __aivicBundle_101_calculateCookingTimeAchievementDegree = (() => {
  function calculateCookingTimeAchievementDegree(input: {
    segmentId: string;
    segmentName: string;
    targetCookingTimeMinutes: number;
    actualCookingTimeMinutes: number;
  }): {
    segmentId: string;
    segmentName: string;
    targetCookingTimeMinutes: number;
    actualCookingTimeMinutes: number;
    achievementDegreePercentage: number;
    timeDifferenceMinutes: number;
    status: 'achieved' | 'not_achieved';
  } {
    const timeDifferenceMinutes = input.targetCookingTimeMinutes - input.actualCookingTimeMinutes;
    
    let achievementDegreePercentage: number;
    if (input.targetCookingTimeMinutes <= 0) {
      achievementDegreePercentage = 0;
    } else if (input.actualCookingTimeMinutes <= 0) {
      achievementDegreePercentage = 100;
    } else if (input.actualCookingTimeMinutes <= input.targetCookingTimeMinutes) {
      achievementDegreePercentage = 100;
    } else {
      const reductionRate = (input.targetCookingTimeMinutes / input.actualCookingTimeMinutes) * 100;
      achievementDegreePercentage = Math.min(reductionRate, 100);
    }
  
    const status = achievementDegreePercentage >= 100 ? 'achieved' : 'not_achieved';
  
    return {
      segmentId: input.segmentId,
      segmentName: input.segmentName,
      targetCookingTimeMinutes: input.targetCookingTimeMinutes,
      actualCookingTimeMinutes: input.actualCookingTimeMinutes,
      achievementDegreePercentage,
      timeDifferenceMinutes,
      status,
    };
  }
  return { calculateCookingTimeAchievementDegree };
})();
