/* AIVIC_FUNCTION_BUNDLE_START owner=prioritizeSegmentsByDifferentiationEffect exports=prioritizeSegmentsByDifferentiationEffect */
const __aivicBundle_102_prioritizeSegmentsByDifferentiationEffect = (() => {
  function prioritizeSegmentsByDifferentiationEffect(
    segmentData: Array<{
      segmentId: string;
      segmentName: string;
      improvementEffect?: number;
      occurrenceFrequency?: number;
      mealGenerationSuccessRate?: number;
      cookingTimeReductionRate?: number;
      userSatisfactionScore?: number;
      proposalAdoptionRate?: number;
      repeatUsageRate?: number;
    }>
  ): Array<{
    segmentId: string;
    segmentName: string;
    differentiationScore?: number;
    priorityRank?: number;
    recommendedAction?: string;
    priority?: number;
    improvementEffect?: number;
    occurrenceFrequency?: number;
  }> {
    if (!segmentData || segmentData.length === 0) {
      return [];
    }
  
    // 各セグメントのスコアを計算
    const scoredSegments = segmentData.map((segment) => {
      let score: number;
  
      // improvementEffect と occurrenceFrequency が存在する場合（テストケース）
      if (
        segment.improvementEffect !== undefined &&
        segment.occurrenceFrequency !== undefined
      ) {
        score = segment.improvementEffect * segment.occurrenceFrequency;
      } else {
        // mealGenerationSuccessRate 等が存在する場合（プラン仕様）
        const successRate = segment.mealGenerationSuccessRate ?? 0;
        const cookingTimeReduction = segment.cookingTimeReductionRate ?? 0;
        const satisfaction = segment.userSatisfactionScore ?? 0;
        const adoptionRate = segment.proposalAdoptionRate ?? 0;
        const repeatUsage = segment.repeatUsageRate ?? 0;
  
        // 加重平均: 各指標を正規化して計算
        score =
          (successRate * 0.25 +
            cookingTimeReduction * 0.2 +
            satisfaction * 0.25 +
            adoptionRate * 0.15 +
            repeatUsage * 0.15) /
          100;
      }
  
      return {
        ...segment,
        score,
      };
    });
  
    // スコアの降順でソート（スコアが同じ場合は occurrenceFrequency の降順）
    const sorted = scoredSegments.sort((a, b) => {
      if (b.score !== a.score) {
        return b.score - a.score;
      }
      // スコアが同じ場合は occurrenceFrequency で比較
      const freqB = b.occurrenceFrequency ?? 0;
      const freqA = a.occurrenceFrequency ?? 0;
      return freqB - freqA;
    });
  
    // 優先度ランキングを付与して結果を構築
    return sorted.map((segment, index) => {
      const priority = index + 1;
      let recommendedAction = "";
  
      if (priority === 1) {
        recommendedAction = "最優先で展開・最適化を推進";
      } else if (priority <= Math.ceil(sorted.length / 2)) {
        recommendedAction = "次段階での展開を検討";
      } else {
        recommendedAction = "継続監視・改善機会を探索";
      }
  
      return {
        segmentId: segment.segmentId,
        segmentName: segment.segmentName,
        differentiationScore: segment.score,
        priorityRank: priority,
        priority,
        recommendedAction,
        improvementEffect: segment.improvementEffect,
        occurrenceFrequency: segment.occurrenceFrequency,
      };
    });
  }
  return { prioritizeSegmentsByDifferentiationEffect };
})();
export const prioritizeSegmentsByDifferentiationEffect = __aivicBundle_102_prioritizeSegmentsByDifferentiationEffect.prioritizeSegmentsByDifferentiationEffect;
