/* AIVIC_FUNCTION_BUNDLE_START owner=assignPrioritiesToDifferentiationFeatures exports=assignPrioritiesToDifferentiationFeatures */
const __aivicBundle_103_assignPrioritiesToDifferentiationFeatures = (() => {
  interface AssignPrioritiesToDifferentiationFeaturesInput {
    segmentAnalysisData: {
      segments: Array<{
        segmentId: string;
        segmentName: string;
        userCount: number;
        mealtimePreferenceScore: number;
        budgetSensitivity: number;
        nutritionFocusScore: number;
        mealPlanAcceptanceRate: number;
        cookingTimeReductionAchievement: number;
        userSatisfactionScore: number;
        featureUsageFrequency: Record<string, number>;
        sessionDurationMinutes: number;
        conversionRate: number;
        churnRate: number;
      }>;
      analysisDate: string;
    };
    differentiationFeatureCandidates: Array<{
      featureId: string;
      featureName: string;
      estimatedImplementationDifficulty: number;
      expectedROIPercentage: number;
      targetSegmentIds: string[];
    }>;
  }
  
  interface PrioritizedFeature {
    featureName: string;
    priorityScore: number;
    priorityRank: number;
    targetSegmentAllocation: {
      primarySegment: string;
      secondarySegments: string[];
    };
  }
  
  interface PhaseRolloutPlan {
    phaseName: string;
    allocatedPercentage: number;
    targetedFeatures: string[];
  }
  
  interface AllocationStrategy {
    totalAllocatedResources: number;
    phaseRolloutPlan: PhaseRolloutPlan[];
  }
  
  interface PrioritizationLogic {
    roiWeightage: number;
    implementationDifficultyWeightage: number;
    segmentCoverageWeightage: number;
  }
  
  interface AssignPrioritiesToDifferentiationFeaturesOutput {
    prioritizedFeatures: PrioritizedFeature[];
    allocationStrategy: AllocationStrategy;
    prioritizationLogic: PrioritizationLogic;
    generatedAt: string;
  }
  
   function assignPrioritiesToDifferentiationFeatures(
    input: AssignPrioritiesToDifferentiationFeaturesInput
  ): AssignPrioritiesToDifferentiationFeaturesOutput {
    const { segmentAnalysisData, differentiationFeatureCandidates } = input;
  
    const roiWeightage = 0.4;
    const implementationDifficultyWeightage = 0.3;
    const segmentCoverageWeightage = 0.3;
  
    const featureScores = differentiationFeatureCandidates.map((feature) => {
      const segmentCoverageScore = calculateSegmentCoverageScore(
        feature.targetSegmentIds,
        segmentAnalysisData.segments
      );
  
      const normalizedROI = feature.expectedROIPercentage / 100;
      const normalizedDifficulty =
        1 - feature.estimatedImplementationDifficulty / 100;
  
      const priorityScore = Math.round(
        roiWeightage * normalizedROI * 100 +
          implementationDifficultyWeightage * normalizedDifficulty * 100 +
          segmentCoverageWeightage * segmentCoverageScore * 100
      );
  
      const primarySegment = determinePrimarySegment(
        feature.targetSegmentIds,
        segmentAnalysisData.segments,
        feature.featureName
      );
  
      const secondarySegments = feature.targetSegmentIds.filter(
        (id) => id !== primarySegment
      );
  
      return {
        featureName: feature.featureName,
        priorityScore,
        targetSegmentAllocation: {
          primarySegment,
          secondarySegments,
        },
      };
    });
  
    const sortedFeatures = featureScores.sort(
      (a, b) => b.priorityScore - a.priorityScore
    );
  
    const prioritizedFeatures = sortedFeatures.map((feature, index) => ({
      ...feature,
      priorityRank: index + 1,
    }));
  
    const phaseRolloutPlan = generatePhaseRolloutPlan(prioritizedFeatures);
  
    const allocationStrategy: AllocationStrategy = {
      totalAllocatedResources: 100,
      phaseRolloutPlan,
    };
  
    const prioritizationLogic: PrioritizationLogic = {
      roiWeightage,
      implementationDifficultyWeightage,
      segmentCoverageWeightage,
    };
  
    const generatedAt = new Date().toISOString();
  
    return {
      prioritizedFeatures,
      allocationStrategy,
      prioritizationLogic,
      generatedAt,
    };
  }
  
  function calculateSegmentCoverageScore(
    targetSegmentIds: string[],
    segments: Array<{ segmentId: string; userCount: number }>
  ): number {
    const totalUserCount = segments.reduce((sum, seg) => sum + seg.userCount, 0);
    const targetUserCount = segments
      .filter((seg) => targetSegmentIds.includes(seg.segmentId))
      .reduce((sum, seg) => sum + seg.userCount, 0);
  
    return totalUserCount > 0 ? targetUserCount / totalUserCount : 0;
  }
  
  function determinePrimarySegment(
    targetSegmentIds: string[],
    segments: Array<{
      segmentId: string;
      nutritionFocusScore: number;
      featureUsageFrequency: Record<string, number>;
    }>,
    featureName: string
  ): string {
    let bestSegmentId = targetSegmentIds[0];
    let bestScore = -1;
  
    for (const segmentId of targetSegmentIds) {
      const segment = segments.find((s) => s.segmentId === segmentId);
      if (!segment) continue;
  
      const featureUsage = segment.featureUsageFrequency[featureName] || 0;
      const nutritionScore = segment.nutritionFocusScore || 0;
  
      const combinedScore = featureUsage * 0.6 + nutritionScore * 0.4;
  
      if (combinedScore > bestScore) {
        bestScore = combinedScore;
        bestSegmentId = segmentId;
      }
    }
  
    return bestSegmentId;
  }
  
  function generatePhaseRolloutPlan(
    prioritizedFeatures: Array<{
      featureName: string;
      priorityRank: number;
    }>
  ): PhaseRolloutPlan[] {
    const phase1Features = prioritizedFeatures
      .filter((f) => f.priorityRank === 1)
      .map((f) => f.featureName);
  
    const phase2Features = prioritizedFeatures
      .filter((f) => f.priorityRank === 2)
      .map((f) => f.featureName);
  
    const phase3Features = prioritizedFeatures
      .filter((f) => f.priorityRank >= 3)
      .map((f) => f.featureName);
  
    return [
      {
        phaseName: 'Phase 1',
        allocatedPercentage: 40,
        targetedFeatures: phase1Features,
      },
      {
        phaseName: 'Phase 2',
        allocatedPercentage: 35,
        targetedFeatures: phase2Features,
      },
      {
        phaseName: 'Phase 3',
        allocatedPercentage: 25,
        targetedFeatures: phase3Features,
      },
    ];
  }
  return { assignPrioritiesToDifferentiationFeatures };
})();
export const assignPrioritiesToDifferentiationFeatures = __aivicBundle_103_assignPrioritiesToDifferentiationFeatures.assignPrioritiesToDifferentiationFeatures;
/* AIVIC_FUNCTION_BUNDLE_END owner=assignPrioritiesToDifferentiationFeatures */

/* AIVIC_FUNCTION_BUNDLE_START owner=assignPriorityWithPainQuantification exports=assignPriorityWithPainQuantification */
const __aivicBundle_104_assignPriorityWithPainQuantification = (() => {
  function assignPriorityWithPainQuantification(input: any): any {
    // Validation: Check for required fields
    const requiredFields = [
      'userCount',
      'impactScore',
      'resolutionTimeMinutes',
      'segmentAffectedCount',
      'satisfactionGainScore',
      'painCategoryId',
      'painCategoryName',
      'detectionFrequency',
      'implementationDifficulty',
    ];
  
    const missingFields = requiredFields.filter(
      (field) => input[field] === undefined || input[field] === null
    );
  
    if (missingFields.length > 0) {
      throw new Error(`必須項目が不足しています: ${missingFields.join(', ')}`);
    }
  
    // Validation: userCount must be > 0
    if (typeof input.userCount !== 'number' || input.userCount <= 0) {
      throw new Error('ユーザー数は0より大きい値である必要があります');
    }
  
    // Validation: impactScore must be 0-100
    if (
      typeof input.impactScore !== 'number' ||
      input.impactScore < 0 ||
      input.impactScore > 100
    ) {
      throw new Error('影響度は0から100の範囲である必要があります');
    }
  
    // Validation: satisfactionGainScore must be 0-100
    if (
      typeof input.satisfactionGainScore !== 'number' ||
      input.satisfactionGainScore < 0 ||
      input.satisfactionGainScore > 100
    ) {
      throw new Error('満足度は0から100の範囲である必要があります');
    }
  
    // Validation: implementationDifficulty must be 1-5
    if (
      typeof input.implementationDifficulty !== 'number' ||
      input.implementationDifficulty < 1 ||
      input.implementationDifficulty > 5
    ) {
      throw new Error('実装難度は1から5の範囲である必要があります');
    }
  
    // Validation: resolutionTimeMinutes must be >= 0
    if (
      typeof input.resolutionTimeMinutes !== 'number' ||
      input.resolutionTimeMinutes < 0
    ) {
      throw new Error('解決時間は0以上である必要があります');
    }
  
    // Validation: detectionFrequency must be > 0
    if (
      typeof input.detectionFrequency !== 'number' ||
      input.detectionFrequency <= 0
    ) {
      throw new Error('検出頻度は0より大きい値である必要があります');
    }
  
    // Calculate priority score based on business metrics
    const userImpactFactor = (input.segmentAffectedCount / input.userCount) * 100;
    const impactComponent = input.impactScore * 0.3;
    const satisfactionComponent = input.satisfactionGainScore * 0.25;
    const frequencyComponent = input.detectionFrequency * 100 * 0.2;
    const difficultyComponent =
      ((6 - input.implementationDifficulty) / 5) * 100 * 0.15;
    const userAffectionComponent = userImpactFactor * 0.1;
  
    const priorityScore =
      impactComponent +
      satisfactionComponent +
      frequencyComponent +
      difficultyComponent +
      userAffectionComponent;
  
    // Determine priority rank based on score
    let priorityRank: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';
    if (priorityScore >= 75) {
      priorityRank = 'CRITICAL';
    } else if (priorityScore >= 50) {
      priorityRank = 'HIGH';
    } else if (priorityScore >= 30) {
      priorityRank = 'MEDIUM';
    } else {
      priorityRank = 'LOW';
    }
  
    // Round priority score to 2 decimal places
    const roundedPriorityScore = Math.round(priorityScore * 100) / 100;
  
    return {
      userCount: input.userCount,
      impactScore: input.impactScore,
      resolutionTimeMinutes: input.resolutionTimeMinutes,
      segmentAffectedCount: input.segmentAffectedCount,
      satisfactionGainScore: input.satisfactionGainScore,
      painCategoryId: input.painCategoryId,
      painCategoryName: input.painCategoryName,
      detectionFrequency: input.detectionFrequency,
      implementationDifficulty: input.implementationDifficulty,
      priorityScore: roundedPriorityScore,
      priorityRank: priorityRank,
    };
  }
  return { assignPriorityWithPainQuantification };
})();
