/* AIVIC_FUNCTION_BUNDLE_START owner=detectOutliersAndValidateQuality exports=detectOutliersAndValidateQuality */
const __aivicBundle_108_detectOutliersAndValidateQuality = (() => {
  function detectOutliersAndValidateQuality(evaluationData: any[]): any {
    if (!evaluationData || evaluationData.length === 0) {
      return {
        isValid: true,
        detectedOutliers: [],
        retainedIndicators: [],
        excludedIndicators: [],
        qualityScore: 100,
        report: {
          totalRecords: 0,
          validRecords: 0,
          outlierRecords: 0,
          generatedAt: new Date().toISOString(),
        },
      };
    }
  
    const detectedOutliers: any[] = [];
    const retainedIndicators: any[] = [];
    const excludedIndicators: any[] = [];
  
    // 統計量計算用
    const cookingTimes: number[] = [];
    const nutritionScores: number[] = [];
    const satisfactionScores: number[] = [];
    const completionRates: number[] = [];
  
    // 第1パス：有効な数値を収集
    evaluationData.forEach((record: any) => {
      if (typeof record.cookingTimeMinutes === 'number') {
        cookingTimes.push(record.cookingTimeMinutes);
      }
      if (typeof record.nutritionScorePoints === 'number') {
        nutritionScores.push(record.nutritionScorePoints);
      }
      if (typeof record.satisfactionScore === 'number') {
        satisfactionScores.push(record.satisfactionScore);
      }
      if (typeof record.completionRate === 'number') {
        completionRates.push(record.completionRate);
      }
    });
  
    // 統計量計算
    const calculateStats = (values: number[]) => {
      if (values.length === 0) return { mean: 0, stdDev: 0 };
      const mean = values.reduce((a, b) => a + b, 0) / values.length;
      const variance =
        values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length;
      const stdDev = Math.sqrt(variance);
      return { mean, stdDev };
    };
  
    const cookingTimeStats = calculateStats(cookingTimes);
    const nutritionScoreStats = calculateStats(nutritionScores);
    const satisfactionScoreStats = calculateStats(satisfactionScores);
    const completionRateStats = calculateStats(completionRates);
  
    // 第2パス：外れ値検出
    evaluationData.forEach((record: any, index: number) => {
      const reasons: string[] = [];
      let isOutlier = false;
  
      // 調理時間の外れ値検出（±2σ）
      if (typeof record.cookingTimeMinutes === 'number') {
        if (
          record.cookingTimeMinutes <
            cookingTimeStats.mean - 2 * cookingTimeStats.stdDev ||
          record.cookingTimeMinutes >
            cookingTimeStats.mean + 2 * cookingTimeStats.stdDev
        ) {
          reasons.push('cookingTimeMinutes_exceeds_threshold');
          isOutlier = true;
        }
      }
  
      // 栄養スコアの外れ値検出
      if (typeof record.nutritionScorePoints === 'number') {
        if (record.nutritionScorePoints < 0) {
          reasons.push('nutritionScorePoints_negative_value');
          isOutlier = true;
        } else if (record.nutritionScorePoints > 100) {
          reasons.push('nutritionScorePoints_exceeds_maximum');
          isOutlier = true;
        } else if (
          record.nutritionScorePoints <
            nutritionScoreStats.mean - 2 * nutritionScoreStats.stdDev ||
          record.nutritionScorePoints >
            nutritionScoreStats.mean + 2 * nutritionScoreStats.stdDev
        ) {
          reasons.push('nutritionScorePoints_exceeds_threshold');
          isOutlier = true;
        }
      }
  
      // 満足度スコアの外れ値検出（±2σ）
      if (typeof record.satisfactionScore === 'number') {
        if (
          record.satisfactionScore <
            satisfactionScoreStats.mean - 2 * satisfactionScoreStats.stdDev ||
          record.satisfactionScore >
            satisfactionScoreStats.mean + 2 * satisfactionScoreStats.stdDev
        ) {
          reasons.push('satisfactionScore_exceeds_threshold');
          isOutlier = true;
        }
      }
  
      // 完食度の外れ値検出（±2σ）
      if (typeof record.completionRate === 'number') {
        if (
          record.completionRate <
            completionRateStats.mean - 2 * completionRateStats.stdDev ||
          record.completionRate >
            completionRateStats.mean + 2 * completionRateStats.stdDev
        ) {
          reasons.push('completionRate_exceeds_threshold');
          isOutlier = true;
        }
      }
  
      if (isOutlier) {
        detectedOutliers.push({
          index,
          ...record,
          reasons,
        });
        excludedIndicators.push(record);
      } else {
        retainedIndicators.push(record);
      }
    });
  
    // 品質スコア計算（正常データの割合 × 100）
    const qualityScore =
      evaluationData.length > 0
        ? Math.round((retainedIndicators.length / evaluationData.length) * 100)
        : 100;
  
    const isValid = qualityScore >= 85;
  
    return {
      isValid,
      detectedOutliers,
      retainedIndicators,
      excludedIndicators,
      qualityScore,
      report: {
        totalRecords: evaluationData.length,
        validRecords: retainedIndicators.length,
        outlierRecords: detectedOutliers.length,
        generatedAt: new Date().toISOString(),
      },
    };
  }
  return { detectOutliersAndValidateQuality };
})();
export const detectOutliersAndValidateQuality = __aivicBundle_108_detectOutliersAndValidateQuality.detectOutliersAndValidateQuality;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectOutliersAndValidateQuality */

/* AIVIC_FUNCTION_BUNDLE_START owner=detectAnomaliesWithFallback exports=detectAnomaliesWithFallback */
const __aivicBundle_109_detectAnomaliesWithFallback = (() => {
  function detectAnomaliesWithFallback(
    input: any
  ): {
    anomalousRecords: EvaluationRecord[];
    cleanRecords: EvaluationRecord[];
    fallbackApplied: boolean;
    fallbackReason?: string;
    trustScore: number;
  } {
    // Validate required input structure
    if (!input || typeof input !== "object") {
      throw new Error("入力データが不正です");
    }
  
    const utilizationLogs = input.utilizationLogs;
    
    
  
    // Check if utilizationLogs is provided and is an array
    if (!Array.isArray(utilizationLogs)) {
      throw new Error("利用ログが必要です");
    }
  
    if (utilizationLogs.length === 0) {
      throw new Error("利用ログが欠落しています");
    }
  
    const anomalousRecords: EvaluationRecord[] = [];
    const cleanRecords: EvaluationRecord[] = [];
    let fallbackApplied = false;
    let fallbackReason: string | undefined;
    let trustScore = 1.0;
  
    // Process each evaluation record from utilizationLogs
    for (const record of utilizationLogs) {
      const isAnomalous = detectAnomalyInRecord(record);
  
      if (isAnomalous) {
        anomalousRecords.push(convertToEvaluationRecord(record));
        trustScore -= 0.15; // Reduce trust score for each anomaly
      } else {
        cleanRecords.push(convertToEvaluationRecord(record));
      }
    }
  
    // Normalize trust score to 0-1 range
    trustScore = Math.max(0, Math.min(1, trustScore));
  
    // If all records are anomalous and fallback strategy is provided, apply fallback
    if (
      anomalousRecords.length === utilizationLogs.length &&
      input.fallbackStrategy === "use_cache"
    ) {
      fallbackApplied = true;
      fallbackReason = "外部データ不足";
      trustScore = Math.max(0.5, trustScore - 0.15); // Further reduce trust for fallback
    }
  
    return {
      anomalousRecords,
      cleanRecords,
      fallbackApplied,
      fallbackReason,
      trustScore,
    };
  }
  
  function detectAnomalyInRecord(record: any): boolean {
    // Check for missing or invalid fields
    if (
      record.satisfactionScore === undefined ||
      record.completionRate === undefined
    ) {
      return true;
    }
  
    const satisfactionScore = Number(record.satisfactionScore);
    const completionRate = Number(record.completionRate);
  
    // Check for out-of-range values
    if (satisfactionScore < 1 || satisfactionScore > 5) {
      return true;
    }
  
    if (completionRate < 0 || completionRate > 100) {
      return true;
    }
  
    // Check for logical contradictions
    // High completion rate (100%) with very low satisfaction (1) is suspicious
    if (completionRate === 100 && satisfactionScore === 1) {
      return true;
    }
  
    // Very low completion rate with high satisfaction is suspicious
    if (completionRate < 20 && satisfactionScore >= 4) {
      return true;
    }
  
    return false;
  }
  
  function convertToEvaluationRecord(record: any): EvaluationRecord {
    return {
      evaluationId: record.evaluationId || `eval-${Date.now()}-${Math.random()}`,
      userId: record.userId,
      familyMemberId: record.familyMemberId || record.family_member_id,
      mealId: record.mealId || record.meal_id,
      satisfactionScore: Number(record.satisfactionScore || record.satisfaction_score || 0),
      completionRate: Number(record.completionRate || record.completion_rate || 0),
      requestContent: record.requestText || record.request || record.request_content,
      timestamp: record.timestamp,
      trustworthinessFlag: record.trustworthinessFlag,
      exclusionFlag: record.exclusionFlag || false,
    };
  }
  return { detectAnomaliesWithFallback };
})();
export const detectAnomaliesWithFallback = __aivicBundle_109_detectAnomaliesWithFallback.detectAnomaliesWithFallback;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectAnomaliesWithFallback */

/* AIVIC_FUNCTION_BUNDLE_START owner=detectOutliers exports=detectOutliers */
const __aivicBundle_110_detectOutliers = (() => {
  function detectOutliers(input: {
    value: number;
    mean: number;
    stdDev: number;
  }): {
    isOutlier: boolean;
    value: number;
  } {
    const { value, mean, stdDev } = input;
    
    const threshold = 3;
    const upperBound = mean + threshold * stdDev;
    const lowerBound = mean - threshold * stdDev;
    
    const isOutlier = value > upperBound || value < lowerBound;
    
    return {
      isOutlier,
      value,
    };
  }
  return { detectOutliers };
})();
export const detectOutliers = __aivicBundle_110_detectOutliers.detectOutliers;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectOutliers */

