/* AIVIC_FUNCTION_BUNDLE_END owner=validateAndExtractQualityPassedData */

/* AIVIC_FUNCTION_BUNDLE_START owner=extractFilteredMetricsData exports=extractFilteredMetricsData */
const __aivicBundle_113_extractFilteredMetricsData = (() => {
  function extractFilteredMetricsData(
    metricsDataset: Array<{ [key: string]: any }>,
    filterCriteria: { [key: string]: any }
  ): {
    data?: Array<{ [key: string]: any }>;
    filteredMetrics?: Array<{ [key: string]: any }> | null;
    filterApplied?: Array<string>;
    matchCount?: number;
    total_count?: number;
    totalCount?: number;
    filterStatus?: string;
  } {
    if (!metricsDataset || metricsDataset.length === 0) {
      return {
        data: [],
        filteredMetrics: null,
        filterApplied: [],
        matchCount: 0,
        total_count: 0,
        totalCount: 0,
        filterStatus: "no_data",
      };
    }
  
    
    const appliedFilters: string[] = [];
    let filtered = [...metricsDataset];
  
    // Handle cooking_time_reduction_score filter
    if (
      filterCriteria.cooking_time_reduction_score !== undefined &&
      filterCriteria.cooking_time_reduction_score !== null
    ) {
      const targetScore = filterCriteria.cooking_time_reduction_score;
      filtered = filtered.filter(
        (item) => item.cooking_time_reduction_score === targetScore
      );
      appliedFilters.push("cooking_time_reduction_score");
    }
  
    // Handle categories filter
    if (
      filterCriteria.categories &&
      Array.isArray(filterCriteria.categories) &&
      filterCriteria.categories.length > 0
    ) {
      filtered = filtered.filter((item) =>
        filterCriteria.categories.includes(item.category)
      );
      appliedFilters.push("category");
    }
  
    // Handle statusFilter
    if (filterCriteria.statusFilter) {
      filtered = filtered.filter(
        (item) => item.status === filterCriteria.statusFilter
      );
      appliedFilters.push("status");
    }
  
    // Handle valueRange filter
    if (filterCriteria.valueRange) {
      const { min, max } = filterCriteria.valueRange;
      filtered = filtered.filter((item) => {
        const value = item.value;
        if (min !== undefined && value < min) return false;
        if (max !== undefined && value > max) return false;
        return true;
      });
      appliedFilters.push("valueRange");
    }
  
    // Handle dateRange filter
    if (filterCriteria.dateRange) {
      const { startDate, endDate } = filterCriteria.dateRange;
      filtered = filtered.filter((item) => {
        const itemDate = new Date(item.timestamp).getTime();
        if (startDate && itemDate < new Date(startDate).getTime()) return false;
        if (endDate && itemDate > new Date(endDate).getTime()) return false;
        return true;
      });
      appliedFilters.push("dateRange");
    }
  
    const matchCount = filtered.length;
    const filterStatus =
      matchCount === 0
        ? "no_match"
        : appliedFilters.length > 0
          ? "success"
          : "no_filter";
  
    return {
      data: filtered,
      filteredMetrics: filtered.length > 0 ? filtered : null,
      filterApplied: appliedFilters,
      matchCount,
      total_count: matchCount,
      totalCount: matchCount,
      filterStatus,
    };
  }
  return { extractFilteredMetricsData };
})();
export const extractFilteredMetricsData = __aivicBundle_113_extractFilteredMetricsData.extractFilteredMetricsData;
/* AIVIC_FUNCTION_BUNDLE_END owner=extractFilteredMetricsData */

